const body = $input.first().json.body || $input.first().json;
const cq = body.callback_query || {};
const data = cq.data || '';
const parts = data.split(':');
const action = parts[0] || '';
const text = (cq.message && cq.message.text) || '';

const pathMatch = text.match(/Path:\s*(.+)/);
const fileMatch = text.match(/File:\s*(.+)/);
const hashMatch = text.match(/([a-f0-9]{64})/i);
const urlMatch  = text.match(/URL:\*?\s*(\S+)/i);   // dari pesan phishing

const isPhishing = (action === 'pblk' || action === 'pign');
const doBlock    = (action === 'iso'  || action === 'pblk');   // ada tindakan AR

const decidedAt = new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Makassar' });

return [{ json: {
  decidedAt,
  action, doBlock, isPhishing,
  agentId:  parts[1] || '000',
  filePath: pathMatch ? pathMatch[1].trim() : '',
  fileName: fileMatch ? fileMatch[1].trim() : '',
  hash:     hashMatch ? hashMatch[1] : '',
  url:      urlMatch ? urlMatch[1].trim() : '',
  chatId:    cq.message ? cq.message.chat.id : '',
  messageId: cq.message ? cq.message.message_id : '',
  callbackQueryId: cq.id || '',
  analyst: (cq.from && (cq.from.first_name || cq.from.username)) || 'analis',
  origText: text
}}];

const token = $('Get Wazuh Token').first().json.data.token;
const p = $('Parse Keputusan').first().json;
const agentId = p.agentId;

// pilih AR sesuai jenis alert: phishing -> block-domain(url), malware -> quarantine-file(path)
let command, arg;
if (p.action === 'pblk') { command = '!block-domain';    arg = p.url; }
else                     { command = '!quarantine-file'; arg = p.filePath; }

const response = await this.helpers.httpRequest({
  method: 'PUT',
  url: `https://172.17.0.1:55000/active-response?agents_list=${agentId}&wait_for_complete=true`,
  headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ command, arguments: [arg] }),
  rejectUnauthorized: false, timeout: 30000
});
return [{ json: { ar_response: response, command, arg, agentId,
  status: (response && response.error === 0) ? 'terkirim' : 'gagal' } }];

